CREATE OR REPLACE FUNCTION public.spotlight_week_start(p_day date) RETURNS date LANGUAGE sql IMMUTABLE AS $$ SELECT (p_day - ((extract(isodow FROM p_day)::int) - 1))::date $$;
CREATE OR REPLACE FUNCTION public.spotlight_price_cents() RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT 3900 $$;
CREATE OR REPLACE FUNCTION public.spotlight_slots() RETURNS int LANGUAGE sql IMMUTABLE AS $$ SELECT 3 $$;
CREATE OR REPLACE FUNCTION public.spotlight_taken(p_city uuid, p_week date) RETURNS int LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT count(*)::int FROM public.spotlight_bookings WHERE city_id = p_city AND week_start = p_week AND (status = 'active' OR (status = 'pending_payment' AND reserved_until > now())) $$;
CREATE OR REPLACE FUNCTION public.spotlight_weeks(p_city uuid, p_restaurant uuid DEFAULT NULL) RETURNS TABLE (week_start date, places_left int, mine boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT w::date, greatest(0, public.spotlight_slots() - public.spotlight_taken(p_city, w::date)), EXISTS (SELECT 1 FROM public.spotlight_bookings b WHERE b.restaurant_id = p_restaurant AND b.week_start = w::date AND (b.status = 'active' OR (b.status = 'pending_payment' AND b.reserved_until > now()))) FROM generate_series(public.spotlight_week_start(current_date), public.spotlight_week_start(current_date) + 49, interval '7 days') w $$;
GRANT EXECUTE ON FUNCTION public.spotlight_weeks(uuid, uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.spotlight_reserve(p_restaurant uuid, p_user uuid, p_weeks date[], p_headline text, p_body text) RETURNS uuid[] LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_city uuid; v_week date; v_ids uuid[] := ARRAY[]::uuid[]; v_id uuid; BEGIN SELECT city_id INTO v_city FROM public.restaurants WHERE id = p_restaurant AND is_active; IF v_city IS NULL THEN RAISE EXCEPTION 'Restaurant niet gevonden' USING ERRCODE = 'P0001'; END IF; IF coalesce(array_length(p_weeks, 1), 0) = 0 OR array_length(p_weeks, 1) > 8 THEN RAISE EXCEPTION 'Kies 1 tot 8 weken' USING ERRCODE = 'P0001'; END IF; PERFORM pg_advisory_xact_lock(hashtext('spotlight:' || v_city::text)); FOREACH v_week IN ARRAY p_weeks LOOP IF v_week <> public.spotlight_week_start(v_week) OR v_week < public.spotlight_week_start(current_date) OR v_week > public.spotlight_week_start(current_date) + 49 THEN RAISE EXCEPTION 'Deze week kun je niet boeken' USING ERRCODE = 'P0001'; END IF; IF public.spotlight_taken(v_city, v_week) >= public.spotlight_slots() THEN RAISE EXCEPTION 'De week van % is vol', to_char(v_week, 'DD-MM') USING ERRCODE = 'P0001'; END IF; UPDATE public.spotlight_bookings SET status = 'cancelled', updated_at = now() WHERE restaurant_id = p_restaurant AND week_start = v_week AND status = 'pending_payment' AND reserved_until <= now(); INSERT INTO public.spotlight_bookings (restaurant_id, user_id, city_id, week_start, headline, body, reserved_until, amount_cents) VALUES (p_restaurant, p_user, v_city, v_week, left(trim(p_headline), 40), left(trim(p_body), 160), now() + interval '30 minutes', public.spotlight_price_cents()) RETURNING id INTO v_id; v_ids := v_ids || v_id; END LOOP; RETURN v_ids; END $$;
REVOKE ALL ON FUNCTION public.spotlight_reserve(uuid, uuid, date[], text, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.spotlight_reserve(uuid, uuid, date[], text, text) TO service_role;
CREATE OR REPLACE FUNCTION public.city_spotlight(p_city uuid) RETURNS TABLE (restaurant_id uuid, headline text, body text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT b.restaurant_id, b.headline, b.body FROM public.spotlight_bookings b JOIN public.restaurants r ON r.id = b.restaurant_id AND r.is_active WHERE b.city_id = p_city AND b.status = 'active' AND b.week_start = public.spotlight_week_start(current_date) ORDER BY md5(b.id::text || current_date::text) LIMIT 3 $$;
GRANT EXECUTE ON FUNCTION public.city_spotlight(uuid) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.track_paid_metrics(p_items jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_count integer; BEGIN IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' OR jsonb_array_length(p_items) > 60 THEN RETURN 0; END IF; WITH items AS (SELECT (i->>'r')::uuid AS restaurant_id, left(i->>'p', 200) AS page_slug, i->>'s' AS surface, i->>'m' AS metric FROM jsonb_array_elements(p_items) i WHERE jsonb_typeof(i) = 'object' AND i->>'r' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND i->>'m' IN ('impressie', 'klik') AND i->>'s' IN ('gerechtpagina', 'zoeken', 'kaart', 'homepage', 'badge', 'spotlight')), agg AS (SELECT it.restaurant_id, it.page_slug, it.surface, it.metric, count(*)::int AS n FROM items it WHERE (it.surface <> 'spotlight' AND EXISTS (SELECT 1 FROM public.package_orders o WHERE o.restaurant_id = it.restaurant_id AND o.page_slug = it.page_slug AND o.package IN ('founding_partner', 'groei', 'topplek', 'dominant') AND public.founding_partner_live(o.status))) OR (it.surface = 'spotlight' AND it.page_slug = 'spotlight' AND EXISTS (SELECT 1 FROM public.spotlight_bookings sb WHERE sb.restaurant_id = it.restaurant_id AND sb.status = 'active' AND sb.week_start = public.spotlight_week_start(current_date))) GROUP BY 1, 2, 3, 4), ins AS (INSERT INTO public.paid_stats_daily AS s (restaurant_id, page_slug, surface, dag, metric, n) SELECT restaurant_id, page_slug, surface, (now() AT TIME ZONE 'Europe/Amsterdam')::date, metric, n FROM agg ON CONFLICT (restaurant_id, page_slug, surface, dag, metric) DO UPDATE SET n = s.n + EXCLUDED.n RETURNING 1) SELECT count(*) INTO v_count FROM ins; RETURN v_count; END $$;
REVOKE ALL ON FUNCTION public.track_paid_metrics(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.track_paid_metrics(jsonb) TO anon, authenticated;
CREATE OR REPLACE FUNCTION public.owner_paid_stats(p_restaurant_id uuid, p_from date DEFAULT NULL, p_to date DEFAULT NULL) RETURNS TABLE(page_slug text, surface text, metric text, totaal bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(), 'admin') OR public.is_verified_owner(auth.uid(), p_restaurant_id)) THEN RAISE EXCEPTION 'Not authorized to view these statistics' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT s.page_slug, s.surface, s.metric, sum(s.n)::bigint FROM public.paid_stats_daily s WHERE s.restaurant_id = p_restaurant_id AND (p_from IS NULL OR s.dag >= p_from) AND (p_to IS NULL OR s.dag <= p_to) GROUP BY 1, 2, 3 UNION ALL SELECT f.page_slug, 'gerechtpagina', f.metric, sum(f.n)::bigint FROM public.founding_stats_daily f WHERE f.restaurant_id = p_restaurant_id AND (p_from IS NULL OR f.dag >= p_from) AND (p_to IS NULL OR f.dag <= p_to) GROUP BY 1, 3; END $$;
REVOKE ALL ON FUNCTION public.owner_paid_stats(uuid, date, date) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.owner_paid_stats(uuid, date, date) TO authenticated;
CREATE OR REPLACE FUNCTION public.owner_founding_stats(p_restaurant_id uuid, p_from date DEFAULT NULL, p_to date DEFAULT NULL) RETURNS TABLE(page_slug text, metric text, totaal bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(), 'admin') OR public.is_verified_owner(auth.uid(), p_restaurant_id)) THEN RAISE EXCEPTION 'Not authorized to view Founding Partner statistics' USING ERRCODE = '42501'; END IF; RETURN QUERY SELECT u.page_slug, u.metric, sum(u.n)::bigint FROM (SELECT s.page_slug, s.metric, s.n FROM public.paid_stats_daily s WHERE s.restaurant_id = p_restaurant_id AND s.surface <> 'spotlight' AND (p_from IS NULL OR s.dag >= p_from) AND (p_to IS NULL OR s.dag <= p_to) UNION ALL SELECT f.page_slug, f.metric, f.n FROM public.founding_stats_daily f WHERE f.restaurant_id = p_restaurant_id AND (p_from IS NULL OR f.dag >= p_from) AND (p_to IS NULL OR f.dag <= p_to)) u GROUP BY 1, 2; END $$;